const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = data[0];
const D = data[1];
const P = new Array(N);
const C = new Array(N);
for (let i = 0; i < N; i++) {
  P[i] = data[2 + 2 * i];
  C[i] = data[3 + 2 * i];
}

// dp[i] = tempo mínimo para chegar à posição P[i] com o carrinho usando a bateria i
const INF = Infinity;
const dp = new Array(N).fill(INF);
dp[0] = 0;

let ans = INF;
for (let i = 0; i < N; i++) {
  if (dp[i] === INF) continue;
  // terminar a pista usando a bateria i até D
  const cand = dp[i] + ((D - P[i]) * (D - P[i])) / C[i];
  if (cand < ans) ans = cand;
  // ir até a próxima bateria j usando a bateria i (velocidade ótima: v = C[i]/dist)
  for (let j = i + 1; j < N; j++) {
    const d = P[j] - P[i];
    const t = dp[i] + (d * d) / C[i];
    if (t < dp[j]) dp[j] = t;
  }
}

console.log(ans.toFixed(3));
